import { z } from "npm:zod@4.6.5";

const S = z.object({ v: z.string() });
const res = (d: string) => ({
  description: d,
  schema: S,
  lifetime: "infinite" as const,
  garbageCollection: 3,
});

// deno-lint-ignore no-explicit-any
type Ctx = any;
const m = (fn: (ctx: Ctx) => Promise<unknown>) => ({
  description: "repro",
  arguments: z.object({}),
  execute: async (_a: unknown, ctx: Ctx) => {
    const out = await fn(ctx);
    return { dataHandles: Array.isArray(out) ? out : [] };
  },
});

export const model = {
  type: "@test/repro",
  version: "2026.10.14.1",
  globalArguments: z.object({}),
  resources: { alpha: res("a"), beta: res("b"), latest: res("spec named latest") },
  methods: {
    w_ok: m(async (c) => [await c.writeResource("alpha", "alpha-current", { v: "1" })]),
    w_latest: m(async (c) => [await c.writeResource("alpha", "latest", { v: "1" })]),
    w_spec_latest: m(async (c) => [await c.writeResource("latest", "ok-name", { v: "1" })]),
    w_dup: m(async (c) => [
      await c.writeResource("alpha", "shared", { v: "1" }),
      await c.writeResource("beta", "shared", { v: "2" }),
    ]),
    r_latest: m(async (c) => {
      const r = await c.readResource("latest");
      c.logger.info("read {r}", { r: JSON.stringify(r) });
      return [];
    }),
  },
};

