// One-off: declare `license: Apache-2.0` in every manifest and apply the repo's
// bump rules (manifest version, model version, appended identity upgrade entry,
// exact-literal test assertions, RELEASE_NOTES.md).
import { appendUpgradeEntry } from "/home/sme/src/webframp/swamp-ext-latest-sweep/extension-maintenance/extensions/models/maintainer.ts";

const ROOT = "/home/sme/src/webframp/swamp-ext-latest-sweep";
const TODAY = "2026.10.14";
const NEW_VERSION = `${TODAY}.1`;
const DESC =
  "No schema changes — manifest now declares license: Apache-2.0 (SPDX)";

async function* walk(dir: string): AsyncGenerator<string> {
  for await (const e of Deno.readDir(dir)) {
    if (e.name.startsWith(".") || e.name === "node_modules") continue;
    const p = `${dir}/${e.name}`;
    if (e.isDirectory) yield* walk(p);
    else yield p;
  }
}

const manifests: string[] = [];
for await (const p of walk(ROOT)) if (p.endsWith("/manifest.yaml")) manifests.push(p);
manifests.sort();

const report: string[] = [];
for (const mpath of manifests) {
  const dir = mpath.slice(0, -"/manifest.yaml".length);
  let m = await Deno.readTextFile(mpath);
  if (/^license:/m.test(m)) {
    report.push(`SKIP(has license) ${dir}`);
    continue;
  }
  const verMatch = m.match(/^version:\s*["']?(\d{4}\.\d{2}\.\d{2}\.\d+)["']?\s*$/m);
  if (!verMatch) throw new Error(`no version in ${mpath}`);
  const oldVersion = verMatch[1];
  const alreadyBumped = oldVersion === NEW_VERSION;
  let newVersion = oldVersion;
  if (!alreadyBumped) {
    if (oldVersion.startsWith(TODAY + ".")) {
      newVersion = `${TODAY}.${parseInt(oldVersion.split(".")[3]) + 1}`;
    } else newVersion = NEW_VERSION;
  }

  // manifest: license after name, version bump
  m = m.replace(/^(name:.*)$/m, `$1\nlicense: Apache-2.0`);
  if (!alreadyBumped) {
    m = m.replace(/^version:.*$/m, `version: "${newVersion}"`);
  }
  await Deno.writeTextFile(mpath, m);

  // source + tests
  if (!alreadyBumped) {
    for await (const f of walk(`${dir}/extensions`)) {
      if (!f.endsWith(".ts")) continue;
      let c = await Deno.readTextFile(f);
      const orig = c;
      if (f.endsWith("_test.ts")) {
        // exact-literal assertions on the model version
        c = c.replace(
          /(model\.version\s*,\s*)"(\d{4}\.\d{2}\.\d{2}\.\d+)"/g,
          (_s, a, v) => `${a}"${v === oldVersion ? newVersion : v}"`,
        );
        // handled below once model versions are known
      } else {
        const hasUpgrades = /(?:^|[,{]\s*)upgrades:\s*\[/m.test(
          c.replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*/g, ""),
        );
        if (hasUpgrades) {
          const vm = c.match(/^( {2}version:\s*)"(\d{4}\.\d{2}\.\d{2}\.\d+)"/m);
          if (!vm) throw new Error(`model version not found in ${f}`);
          const modelOld = vm[2];
          c = c.replace(vm[0], `${vm[1]}"${newVersion}"`);
          c = appendUpgradeEntry(c, newVersion, DESC);
          // fix exact-literal test assertions for this model's old version
          const testPath = f.replace(/\.ts$/, "_test.ts");
          try {
            let t = await Deno.readTextFile(testPath);
            const t2 = t.replace(
              new RegExp(`(model\\.version\\s*,\\s*)"${modelOld.replaceAll(".", "\\.")}"`, "g"),
              `$1"${newVersion}"`,
            );
            if (t2 !== t) await Deno.writeTextFile(testPath, t2);
          } catch { /* no sibling test */ }
        }
      }
      if (c !== orig) await Deno.writeTextFile(f, c);
    }
  }

  // release notes
  const rnPath = `${dir}/RELEASE_NOTES.md`;
  let existing = "";
  try {
    existing = await Deno.readTextFile(rnPath);
  } catch { /* none */ }
  const added =
    "**Added:** The manifest now declares `license: Apache-2.0` (SPDX). The registry quality rubric scores a declared license separately from the bundled `LICENSE.md`.";
  if (alreadyBumped) {
    // append to the existing 2026.10.14.1 section (top of file)
    const idx = existing.indexOf("\n## ", 1);
    const head = idx === -1 ? existing.trimEnd() : existing.slice(0, idx).trimEnd();
    const tail = idx === -1 ? "" : existing.slice(idx);
    existing = `${head}\n\n${added}\n${tail}`;
    if (!existing.endsWith("\n")) existing += "\n";
    await Deno.writeTextFile(rnPath, existing);
  } else {
    const entry =
      `## ${newVersion}\n\n${added}\n\n**Upgrade note:** Metadata only. No code, schema, or behavioral changes.\n`;
    await Deno.writeTextFile(rnPath, existing ? `${entry}\n${existing}` : entry);
  }
  report.push(`${alreadyBumped ? "LIC-ONLY" : "BUMPED  "} ${oldVersion} -> ${newVersion} ${dir.slice(ROOT.length + 1)}`);
}
console.log(report.join("\n"));
console.log(`total ${manifests.length}`);

